#!/usr/bin/env python3
"""Rimuru skin for Kimi Code Web UI — single-file installer.

Patches the prebuilt web bundle (dist-web): writes rimuru-skin/ assets and
adds one external <script> tag to index.html. Idempotent. Reload the page
afterwards. Auto-detects dist-web; a manual path argument always wins.

  python3 rimuru_skin_install.py [dist-web路径]   # apply (auto-detect if omitted)
  python3 rimuru_skin_install.py --check [路径]   # report install/bundle status
  python3 rimuru_skin_install.py --remove [路径]  # uninstall

The bundle is rebuilt on every kimi-code upgrade / `sync:web`, which wipes the
patch. The installer stamps the bundle fingerprint (index.html hash + hashed
asset names) and the kimi-code version into rimuru-skin/.stamp.json, and warns
whenever the bundle changed since the last patch.
"""
import base64
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
from datetime import datetime, timezone
from pathlib import Path

TAG = '<script src="/rimuru-skin/skin.js" defer></script>'
USAGE = """Rimuru skin for Kimi Code Web UI — single-file installer.

Usage:
  python3 rimuru_skin_install.py                 apply (auto-detect dist-web)
  python3 rimuru_skin_install.py /path/to/dist-web   apply to a specific bundle
  python3 rimuru_skin_install.py --check [path]  report skin/bundle status
                                                 (exit 0 = intact, 1 = needs re-run)
  python3 rimuru_skin_install.py --remove [path] uninstall
  python3 rimuru_skin_install.py --help          show this help

Notes:
  - Apply is idempotent; reload the web UI page afterwards (no server restart).
  - A manual path always wins. Auto-detect tries, in order: source checkout
    (~/kimi-code), npm-global package, `kimi` on PATH, packaged-binary caches
    (~/.cache/kimi-code/web/...). All hits are listed when several exist.
  - Every kimi-code upgrade / sync:web rebuilds the bundle and wipes the patch.
    The installer stamps version + bundle fingerprint into rimuru-skin/.stamp.json
    and warns on re-apply; --check reports CHANGED in that case.
"""
PAYLOAD = {
 "skin.js": "",
 "mesh.json": "",
 "sprite_meshed.png": "",
 "tassel_patch.png": ""
}


# ---------- dist-web discovery ----------

def _candidates():
    yield Path.home() / "kimi-code/apps/kimi-code/dist-web"  # source checkout
    try:
        out = subprocess.run(["npm", "root", "-g"], capture_output=True, text=True, timeout=5)
        if out.returncode == 0:
            yield Path(out.stdout.strip()) / "@moonshot-ai/kimi-code/dist-web"
    except (OSError, subprocess.SubprocessError):
        pass
    for root in ("/usr/local/lib/node_modules", "/usr/lib/node_modules",
                 Path.home() / ".local/share/pnpm/global/5/node_modules"):
        yield Path(root) / "@moonshot-ai/kimi-code/dist-web"
    for name in ("kimi", "kimi-code"):  # resolve the launcher back to its package
        exe = shutil.which(name)
        if not exe:
            continue
        try:
            real = Path(exe).resolve()
        except OSError:
            continue
        for anc in real.parents:
            if (anc / "package.json").is_file():
                yield anc / "dist-web"
                break


def _sea_cache_dirs():
    """dist-web dirs extracted by packaged (SEA) binaries:
    <cache>/kimi-code/web/<version>/<target>/<manifest-hash>/dist-web"""
    bases = []
    if os.environ.get("KIMI_CODE_CACHE_DIR"):
        bases.append(Path(os.environ["KIMI_CODE_CACHE_DIR"]))
    xdg = os.environ.get("XDG_CACHE_HOME")
    bases.append(Path(xdg) / "kimi-code" if xdg else Path.home() / ".cache/kimi-code")
    if sys.platform == "darwin":
        bases.append(Path.home() / "Library/Caches/kimi-code")
    hits = []
    for base in bases:
        hits.extend(p for p in base.glob("web/*/*/*/dist-web") if (p / "index.html").is_file())
    # newest version first — index.html mtime is unreliable (patching bumps it)
    def _ver_key(p):
        m = re.match(r"(\d+)\.(\d+)\.(\d+)", p.parents[2].name)
        if m:
            return (1, tuple(int(g) for g in m.groups()))
        return (0, (p / "index.html").stat().st_mtime)  # fallback: mtime
    hits.sort(key=_ver_key, reverse=True)
    return hits


def find_dist_web(explicit=None):
    if explicit is not None:
        d = Path(explicit).expanduser()
        if not (d / "index.html").is_file():
            sys.exit(f"error: {d}/index.html not found")
        return d
    hits = []
    for c in _candidates():
        c = Path(c)
        if c not in hits and (c / "index.html").is_file():
            hits.append(c)
    for c in _sea_cache_dirs():
        if c not in hits:
            hits.append(c)
    if not hits:
        sys.exit("error: could not auto-detect dist-web; locate it and pass the path manually:\n"
                 "  find ~ -type d -name dist-web 2>/dev/null | head\n"
                 "  python3 rimuru_skin_install.py /path/to/dist-web")
    if len(hits) > 1:
        others = "\n    ".join(str(h) for h in hits[1:])
        print(f"note: multiple dist-web found; patching {hits[0]}\n"
              f"    other candidates (pass as arg to patch instead):\n    {others}")
    return hits[0]


# ---------- version & bundle fingerprint ----------

def kimi_version(dist_web):
    pkg = dist_web.parent / "package.json"
    try:
        return json.loads(pkg.read_text(encoding="utf-8")).get("version", "unknown")
    except (OSError, json.JSONDecodeError):
        return "unknown"


def bundle_fingerprint(dist_web):
    """Stable identity of the shipped bundle: index.html (tag stripped) + the
    hashed /assets/ file names it references — both change on any re-bundle."""
    html = (dist_web / "index.html").read_text(encoding="utf-8").replace(TAG, "")
    assets = sorted(set(re.findall(r"/assets/([\w.-]+)", html)))
    digest = hashlib.sha256(html.encode("utf-8")).hexdigest()[:16]
    return {"index_sha256": digest, "assets": assets}


def stamp_path(dist_web):
    return dist_web / "rimuru-skin" / ".stamp.json"


def read_stamp(dist_web):
    try:
        return json.loads(stamp_path(dist_web).read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None


def write_stamp(dist_web):
    stamp = {
        "kimi_version": kimi_version(dist_web),
        "fingerprint": bundle_fingerprint(dist_web),
        "patched_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
    }
    stamp_path(dist_web).write_text(json.dumps(stamp, indent=2), encoding="utf-8")
    return stamp


# ---------- actions ----------

def materialize(target):
    if target.exists():
        shutil.rmtree(target)
    target.mkdir(parents=True)
    for rel, b64 in PAYLOAD.items():
        dest = target / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(base64.b64decode(b64))


def warn_if_bundle_changed(dist_web, stamp):
    if stamp is None:
        return
    cur_ver = kimi_version(dist_web)
    cur_fp = bundle_fingerprint(dist_web)
    if cur_fp != stamp.get("fingerprint"):
        print(f"WARNING: kimi-code web bundle changed since last patch "
              f"({stamp.get('kimi_version')} -> {cur_ver}); re-applying skin.")


def apply(dist_web):
    prev = read_stamp(dist_web)
    warn_if_bundle_changed(dist_web, prev)
    materialize(dist_web / "rimuru-skin")
    html_path = dist_web / "index.html"
    html = html_path.read_text(encoding="utf-8")
    if TAG not in html:
        if "</body>" not in html:
            sys.exit("error: </body> not found in index.html — unexpected bundle layout")
        html_path.write_text(html.replace("</body>", f"  {TAG}\n  </body>"), encoding="utf-8")
    stamp = write_stamp(dist_web)
    print(f"skin applied: {dist_web} (kimi-code {stamp['kimi_version']}) — reload the web UI page")


def check(dist_web):
    stamp = read_stamp(dist_web)
    tag_ok = TAG in (dist_web / "index.html").read_text(encoding="utf-8")
    assets_ok = (dist_web / "rimuru-skin" / "skin.js").is_file()
    if stamp is None or not assets_ok or not tag_ok:
        print(f"skin NOT fully installed in {dist_web} (tag={tag_ok}, assets={assets_ok})")
        sys.exit(1)
    cur_ver = kimi_version(dist_web)
    changed = bundle_fingerprint(dist_web) != stamp.get("fingerprint")
    print(f"dist-web:     {dist_web}")
    print(f"kimi-code:    {cur_ver} (patched under {stamp.get('kimi_version')}, "
          f"at {stamp.get('patched_at')})")
    print(f"bundle state: {'CHANGED — re-run the installer' if changed else 'unchanged, skin intact'}")
    sys.exit(1 if changed else 0)


def remove(dist_web):
    shutil.rmtree(dist_web / "rimuru-skin", ignore_errors=True)
    html_path = dist_web / "index.html"
    if html_path.is_file():
        html = html_path.read_text(encoding="utf-8")
        html_path.write_text(html.replace(f"  {TAG}\n", "").replace(TAG, ""), encoding="utf-8")
    print("removed")


def main():
    args = sys.argv[1:]
    if "--help" in args or "-h" in args:
        print(USAGE)
        return
    unknown = [a for a in args if a.startswith("-") and a not in ("--check", "--remove")]
    if unknown:
        sys.exit(f"error: unknown option {' '.join(unknown)} — try --help")
    explicit = args[-1] if args and not args[-1].startswith("-") else None
    dist_web = find_dist_web(explicit)
    if "--check" in args:
        check(dist_web)
    elif "--remove" in args:
        remove(dist_web)
    else:
        apply(dist_web)


if __name__ == "__main__":
    main()
